    au = J("annotation_audit.json"); fr = J("final_results.json"); fb = J("final_results_before_gt_fix.json"); er = J("errors.json"); rk = J("ranker.json"); cv = J("cv_ranker.json"); hy = json.loads((ROOT / "models/taskB/hybrid.json").read_text())
    ic = J("inference_check.json"); sm = au["summary"]; SYS = fr["systems"]; ALL = SYS + ["hybrid"]; T = lambda s, sl: fr["by_system"][s]["test"][sl]; V = lambda s, sl: fr["by_system"][s]["val"][sl]
