    o += ["", "`*` = fewer than 20 real test documents: indicative only. Soft-match F1 for text fields (hybrid, real): " + ", ".join(f"{f} {f3(T('hybrid','real')[f].get('soft_f1'))}" for f in ("merchant_name", "merchant_address", "origin", "destination") if f in T("hybrid", "real")) + ".", "",
          "### 10.2 Hybrid per-field detail (real test): precision / recall / F1 for the critical fields", "", "| Field | support | P | R | F1 | exact-raw | null | halluc. |", "|---|---:|---:|---:|---:|---:|---:|---:|"]
