    o += ["", "### 10.3 SYNTHETIC results (separate; NOT evidence of real-world performance)", "", "| System | synthetic micro-F1 | synthetic macro-F1 |", "|---|---:|---:|"]
    for s in ALL: m = T(s, "synthetic"); o.append(f"| {s} | {f3(micro(m, list(m))['f1'])} | {f3(macro(m, list(m)))} |")
